class Solution {
public:
    vector<int> asteroidCollision(vector<int>& asteroids) {
        vector<int> ans;

        for (int asteroid : asteroids) {

            if (asteroid > 0) {
                ans.push_back(asteroid);
            }
            else {
                int x = -asteroid;

                while (!ans.empty() && ans.back() > 0) {

                    if (ans.back() < x) {
                        // positive asteroid explodes
                        ans.pop_back();
                    }
                    else if (ans.back() == x) {
                        // both explode
                        ans.pop_back();
                        x = 0;
                        break;
                    }
                    else {
                        // negative asteroid explodes
                        x = 0;
                        break;
                    }
                }

                if (x != 0) {
                    ans.push_back(-x);
                }
            }
        }

        return ans;
    }
};

class Solution {
public:
    int calPoints(vector<string>& operations) {
        // lets use vector as stack 
        vector<int> ans;
        int pointer = 0;
        for(int i=0;i<operations.size();i++){
            if(operations[i]=="+"){
                int n = ans.size();
                ans.push_back(ans[n-1]+ans[n-2]);
            }
            else if(operations[i]=="C"){
                ans.pop_back();
            }
            else if(operations[i]=="D"){
                ans.push_back(2*ans.back());
            }else{
                ans.push_back(stoi(operations[i]));
            }
        }
        int finalAns = 0;
        for(int i=0;i<ans.size();i++){
            finalAns += ans[i];
        }
        return finalAns;
    }
};

