public:
    bool containsNearbyDuplicate(vector<int>& nums, int k) {
        // we can use set of size k
        int left = 0;
        int right = 0;
        set<int> st;
        while(right<nums.size()){
            if(right-left > k){
                st.erase(nums[left]);
                left++;
            }
            if(st.find(nums[right])!=st.end() && right!=left){
                return true;
            }
            st.insert(nums[right]);
            right++;
        }
        return false;
    }
};

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& arr) {
        // O(n*n) for brute force : will not work
        // daily temperature

        vector<int> ans(arr.size(),0);
        stack<pair<int,int>> st;
        for(int i=0;i<arr.size();i++){
            int temp = arr[i];
            while(st.empty()==false && temp>st.top().first){
                auto pair = st.top();
                st.pop();
                ans[pair.second] = i-pair.second;
            }
            st.push({arr[i],i});
        }
        return ans;
    }
};

class Solution {
public:
    string decodeString(string s) {
        stack<int> countStack;
        stack<string> stringStack;

        string current = "";
        int count = 0;

        for (char ch : s) {

            // Build the number
            if (isdigit(ch)) {
                count = count * 10 + (ch - '0');
            }

            // Entering a new bracket
            else if (ch == '[') {
                countStack.push(count);
                stringStack.push(current);

                count = 0;
                current = "";
            }

            // Leaving a bracket
            else if (ch == ']') {
                int k = countStack.top();
                countStack.pop();

                string previous = stringStack.top();
                stringStack.pop();

                string repeated = "";

                for (int i = 0; i < k; i++) {
                    repeated += current;
                }

                current = previous + repeated;
            }

            // Normal character
            else {
                current += ch;
            }
        }

        return current;
    }
};

