        if(nums.size() == 0){
            return 0;
        }
        unordered_set<int> st(nums.begin(),nums.end());
        int maxi = 1;
        for(auto num : st){
            if(st.find(num-1) == st.end()){
                // num - 1 donot exist
                int len = 1;
                int current = num;
                while(st.find(current+1) != st.end()){
                    current++;
                    len++;
                }

                maxi = max(maxi,len);
            }
        }   
        return maxi;
    }
};

class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        // we have to write algo in O(n) time complexity
        map<int,int> mpp;
        for(int i=0;i<nums.size();i++){
            mpp[nums[i]]++;
        }
        int ansCount = 0;
        for(int i=0;i<nums.size();i++){
            int value = nums[i];
            int temp = 0;
            while(mpp.find(value)!= mpp.end()){
                value--;
            }
            value++;
            while(mpp.find(value)!=mpp.end()){
                temp++;
                value++;
            }
            ansCount = max(ansCount,temp);
        }
        return ansCount;
    }
};

class Solution {
public:
    string longestDiverseString(int a, int b, int c) {

        priority_queue<pair<int, char>> pq;

        if (a > 0) pq.push({a, 'a'});
        if (b > 0) pq.push({b, 'b'});
        if (c > 0) pq.push({c, 'c'});

        string ans = "";

        while (!pq.empty()) {

            auto [freq, ch] = pq.top();
            pq.pop();

            // Can't use this character because it
            // would create three consecutive characters
            if (ans.size() >= 2 &&
                ans[ans.size() - 1] == ch &&
                ans[ans.size() - 2] == ch) {

                // No alternative character available
                if (pq.empty()) {
                    break;
                }

                // Take second most frequent character
                auto [freq2, ch2] = pq.top();
                pq.pop();

                ans += ch2;
                freq2--;

                if (freq2 > 0) {
                    pq.push({freq2, ch2});
                }

                // We didn't use ch, so put it back
                pq.push({freq, ch});
            }
            else {
                // We can safely use ch
                ans += ch;
                freq--;

                if (freq > 0) {
                    pq.push({freq, ch});
                }
            }
        }

        return ans;
    }
};

class Solution {
public:
    int characterReplacement(string s, int k) {
        // using hash array
        int maxLen = 0;
        for(int i=0;i<s.length();i++){
            vector<int>hash(26,0);
            int maxFreq = 0;
            for(int j=i;j<s.length();j++){
                hash[s[j]-'A']++;
                maxFreq = max(maxFreq,hash[s[j]-'A']);
                int changes = j-i+1 - maxFreq;
                if(changes<=k){
                    maxLen = max(maxLen,j-i+1);
                }else{
                    break;
                }
            }
        }
        return maxLen;
    }
};

