class Solution {
public:
    int characterReplacement(string s, int k) {
        int left = 0;
        int right = 0;
        int maxLength = 0;
        int maxFreq = 0;
        map<char,int> mpp;
        while(right<s.length()){
            mpp[s[right]]++;
            maxFreq = max(maxFreq,mpp[s[right]]);

            // we have to check for valid window
            while(right-left+1 - maxFreq > k){
                // we need to shrink the window
                mpp[s[left]]--;
                left++;
            }
            maxLength = max(maxLength,right-left+1);
            right++;
        }
        return maxLength;
    }
};

class Solution {
public:
    int characterReplacement(string s, int k) {
        int ans = 0;
        int left = 0;
        int right = 0;
        int maxFrequency = 0;
        vector<int> freq(26,0);

        while(right<s.length()){
            freq[s[right]-'A']++;
            maxFrequency = max(maxFrequency,freq[s[right]-'A']);

            while((right-left+1)-maxFrequency>k){
                // window is invalid
                freq[s[left]-'A']--;
                left++;
            }
            ans = max(ans,right-left+1);
            right++;
        }
        return ans;
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int l = 0;
        int r = 0;
        int ans = 0;
        vector<int> hash(256,-1);
        while(r<s.length()){
            if(hash[s[r]] != -1){
                if(hash[s[r]]>=l){
                    l = hash[s[r]]+1;
                }
            }
            ans = max(ans,r-l+1);
            hash[s[r]] = r;
            r++;
        }
        return ans;
    }
};

class Solution {
