class Solution {
public:
    int maxArea(vector<int>& heights) {
        int n = heights.size();
        int i = 0;
        int j = n-1;
        int ans = 0;
        while(i<j){
            ans = max(ans,min(heights[i],heights[j])*(j-i));
            if(heights[i]>heights[j]){
                j--;
            }else{
                i++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int maxArea(vector<int>& heights) {
        // two pointer approach
        int i = 0;
        int j = heights.size()-1;
        int ans = 0;
        while(i<j){
            if(heights[i]<=heights[j]){
                ans = max(ans,heights[i]*(j-i));
                i++;
            }else{
                ans = max(ans,heights[j]*(j-i));
                j--;
            }
        }
        return ans;
    }
};

class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        // use three pointer approach
        int i = m-1;
        int j = n-1;
        int k = m+n-1;

        while(i>=0 && j>=0){
            if(nums1[i]>=nums2[j]){
                nums1[k] = nums1[i];
                i--;
                k--;
            }else{
                nums1[k] = nums2[j];
                j--;
                k--;
            }
        }

        while(j>=0){
            nums1[k] = nums2[j];
            k--;
            j--;
        }
    }
};

