/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */

class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        ListNode dummy(0);
        ListNode* mover = &dummy;
        while(list1 != NULL && list2 != NULL){
            if(list1->val <= list2->val){
                mover->next = list1;
                list1 = list1->next;
            }else{
                mover->next = list2;
                list2 = list2->next;
            }
            mover = mover->next;
        }
        while(list1 != NULL){
            mover->next = list1;
            list1 = list1->next;
            mover = mover->next;
        }
        while(list2 != NULL){
            mover->next = list2;
            list2 = list2->next;
            mover = mover->next;
        }
        return dummy.next;        
    }
};

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        // we can't sort it
        // brute force: check for every subarray(not optimal)]

        // maybe we can go for sliding window
        int minLen = INT_MAX;
        int left = 0;
        int right = 0;
        int tempSum = 0;
        while(right<nums.size()){
            tempSum += nums[right];
            while(tempSum >= target){
                minLen = min(minLen,right-left+1);
                tempSum -= nums[left];
                left++;

            }
            right++;
        }
        if(minLen == INT_MAX){
            return 0;
        }
        return minLen;

    }
};

