class MinStack {
public:
    MinStack() {

    }
    stack<pair<int,int>> st;

    void push(int val) {
        if(st.empty()){
            st.push({val,val});
        }else{
            st.push({val,min(val,st.top().second)});
        }
    }

    void pop() {
        st.pop();
    }

    int top() {
        int temp = st.top().first;
        return temp;
    }

    int getMin() {
        return st.top().second;
    }
};

class Solution {
public:
    string minWindow(string s, string t) {

        // edge case
        if(t.length() > s.length()){
            return "";
        }

        vector<int>freq1(256,0);    // current window
        vector<int>freq2(256,0);    // for string t

        for(auto ch:t){
            freq2[ch]++;
        }

        int left = 0;
        int right = 0;

        int minLength = INT_MAX;
        int start = 0;

        while(right < s.length()){

            // Add current character
            freq1[s[right]]++;

            // Check whether current window is valid
            bool flag = true;

            for(int i = 0; i < 256; i++){
                if(freq1[i] < freq2[i]){
                    flag = false;
                    break;
                }
            }

            // If window is valid, try shrinking from left
            while(flag == true){

                // Current window is valid
                int length = right - left + 1;

                // Save smallest window
                if(length < minLength){
                    minLength = length;
                    start = left;
                }

                // Remove left character
                freq1[s[left]]--;
                left++;

                // Check again whether window is valid
                flag = true;

                for(int i = 0; i < 256; i++){
                    if(freq1[i] < freq2[i]){
                        flag = false;
                        break;
                    }
                }
            }

            // Continue expanding
            right++;
        }

        if(minLength == INT_MAX){
            return "";
        }

        string result = "";

        for(int i = start; i < start + minLength; i++){
            result += s[i];
        }

        return result;
    }
};

class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        // edge case
        if(s1.length() > s2.length()){
            return false;
        }

        // we can try for sliding window
        // we can take 2 freq array
        vector<int> freq1(26,0);
        vector<int> freq2(26,0);

        for(auto ch:s1){
            freq1[ch-'a']++;
        }

        int left = 0;
        int right = 0;
        while(right<s2.length()){
            freq2[s2[right]-'a']++;
            // we have to maintain fixed window size of s1 length
            if(right-left+1 > s1.length()){
                freq2[s2[left]-'a']--;
                left++;
            }

            // now matching part
            if(right-left+1 == s1.length()){
                // we have to match both freq array
                bool flag = true;
                for(int i=0;i<26;i++){
                    if(freq1[i]!=freq2[i]){
                        flag = false;
                    }
                }
                if(flag == true){
                    return true;
                }
            }
            right++;
        }
        return false;
    }
};

