/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */

class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        // we can find the length first
        int len = 0;
        ListNode* mover = head;
        while(mover!=NULL){
            len++;
            mover = mover->next;
        }

        int startingPosition = len-n+1;
        ListNode* curr = head;
        ListNode* prev = NULL;
        for(int i=0;i<startingPosition-1;i++){
            prev = curr;
            curr = curr->next;
        }

        if(len == 1 && n==1){
            return NULL;
        }

        if(prev == NULL){
            return curr->next;
        }
        prev->next = curr->next;
        curr->next = NULL;
        return head;

    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */

class Solution {
public:
    ListNode* reverseList(ListNode* head){
        ListNode* curr = head;
        ListNode* front = NULL;
        ListNode* prev = NULL;
        while(curr != NULL){
            front = curr->next;
            curr->next = prev;
            prev = curr;
            curr = front;
        }
        return prev;
    }
    void reorderList(ListNode* head) {
        // think of reversing linked list 

        ListNode* slow = head;
        ListNode* fast = head;
        while(fast!=NULL && fast->next!=NULL){
            slow = slow->next;
            fast = fast->next->next;
        }

        ListNode* second = slow->next;
        slow->next = NULL;

        ListNode* l1 = head;
        ListNode* l2 = reverseList(second);

        ListNode dummy(0);
        ListNode* mover = &dummy;

        while(l1!=NULL || l2!=NULL){
            if(l1 != NULL){
                mover->next = l1;
                l1 = l1->next;
                mover= mover->next; 
            }
            if(l2 != NULL){
                mover->next = l2;
                l2 = l2->next;
                mover = mover->next;
            }
        }    
    }
};

class Solution {
public:
    string reorganizeString(string s) {
        string ans = "";
        vector<int> freq(26,0);
        for(auto ch:s){
            freq[ch-'a']++;
        }
        // now we have count 
        // we have use heap (maxHeap)
        vector<pair<int,char>> temp;
        for(int i=0;i<26;i++){
            if(freq[i]!=0){
                temp.push_back({freq[i],'a'+i});
            }
        }
        priority_queue<pair<int,char>> pq;
        for(int i=0;i<temp.size();i++){
            pq.push({temp[i].first,temp[i].second});
        }

        // we have priority queue
        while(!pq.empty()){
            int count1 = pq.top().first;
            char ch1 = pq.top().second;
            pq.pop();
            ans += ch1;
            count1--;
            if(!pq.empty()){
                int count2 = pq.top().first;
                char ch2 = pq.top().second;
                pq.pop();
                ans += ch2;
                count2--;
                if(count2>0){
                    pq.push({count2,ch2});
                }
            }else if(pq.empty() && count1>0){
                return "";
            }
            if(count1>0){
                pq.push({count1,ch1});
            }
        }
        if(s.length() != ans.length()){
            return "";
        }else{
            return ans;
        }
    }
};

