class Solution {
public:
    string simplifyPath(string path) {

        // left and right used for getting directory name
        vector<string> temp;

        int left = 1;
        int right = 1;

        while (right < path.length()) {

            // Found the end of a directory
            if (path[right] == '/') {

                if (right > left) {

                    string dir = path.substr(left, right - left);

                    if (dir == "..") {

                        if (!temp.empty()) {
                            temp.pop_back();
                        }

                    } 
                    else if (dir == ".") {
                        // do nothing
                    } 
                    else {
                        temp.push_back(dir);
                    }
                }

                // Move left after EVERY slash
                left = right + 1;
            }

            // IMPORTANT: right++ must be INSIDE the loop
            right++;
        }

        // Process the LAST directory
        if (right > left) {

            string dir = path.substr(left, right - left);

            if (dir == "..") {

                if (!temp.empty()) {
                    temp.pop_back();
                }

            } 
            else if (dir == ".") {
                // do nothing
            } 
            else {
                temp.push_back(dir);
            }
        }

        // Build answer
        string ans = "";

        for (int i = 0; i < temp.size(); i++) {
            ans += "/" + temp[i];
        }

        if (ans == "") {
            return "/";
        }

        return ans;
    }
};

class Solution {
public:
    struct Task{
        long long enqueueTime;
        long long processingTime;
        int index;
    };

    vector<int> getOrder(vector<vector<int>>& tasks) {
        vector<int> ans;
        int n = tasks.size();
        vector<Task> sortedTasks;
        for(int i=0;i<n;i++){
            sortedTasks.push_back({tasks[i][0],tasks[i][1],i});
        }

        // lets sort this on basis of enqueueTime
        // this is custome comparator 
        sort(sortedTasks.begin(),sortedTasks.end(),[](Task& a,Task& b){
            return a.enqueueTime < b.enqueueTime;
        });

        // now we have sorted Task
        // lets define priority queue(min Heap)
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pq;

        long long time = 0;
        int i = 0;
        while(i<n || !pq.empty()){

            // if pq.empty() hai
            while(pq.empty() && time<sortedTasks[i].enqueueTime){
                time = sortedTasks[i].enqueueTime;
            }

            // add all task that have arrived
            while(i<n && sortedTasks[i].enqueueTime <= time){
                pq.push({
                    sortedTasks[i].processingTime,sortedTasks[i].index
                });
                i++;
            }
            // now get time with smallest processing time from minHeap 
            long long processingTime = pq.top().first;
            long long index = pq.top().second;
            pq.pop();
            ans.push_back(index);
            time += processingTime;
        }
        return ans;
    }
};

class Solution {
   public:
    void quickSort(vector<int>& nums, int low, int high) {
        // recurssive function
        if (low < high) {
            int partitionIndex = partition(nums, low, high);
            quickSort(nums, low, partitionIndex - 1);
            quickSort(nums, partitionIndex + 1, high);
        }
    }

    int partition(vector<int>& nums,int low,int high){
        int pivot = nums[low];
        int i=low;
        int j=high;
        while(i<j){
            while(i<high && nums[i]<=pivot){
                i++;
            }
            while(j>low && nums[j]>=pivot){
                j--;
            }

            if(i<j){
                swap(nums[i],nums[j]);
            }
        }
        swap(nums[low],nums[j]);
        return j;
    }

    vector<int> sortArray(vector<int>& nums) {
        // applying merge sort will bring space complexity to nlogn
        // so we apply quick sort
        // TC : O(nlogn), SC : O(1)

        int n = nums.size() - 1;
        quickSort(nums, 0, n);
        return nums;
    }
};

