        map<int,int> mpp;
        for(int i=0;i<nums.size();i++){
            mpp[nums[i]]++;
        }

        // create a min heap
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> minHeap;

        for(auto m:mpp){
            minHeap.push({m.second,m.first});
            if(minHeap.size() > k){
                minHeap.pop();
            }
        }

        vector<int> ans;
        for(int i=0;i<k;i++){
            ans.push_back(minHeap.top().second);
            minHeap.pop();
        }
        return ans;

    }
};

class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        vector<int> ans;
        map<int,int> mpp;
        for(int i=0;i<nums.size();i++){
            mpp[nums[i]]++;
        }

        // creating minHeap
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> minHeap;

        for(auto m : mpp){
            minHeap.push({m.second,m.first});
            if(minHeap.size() > k){
                minHeap.pop();
            }
        }
        while(minHeap.size() != 0){
            ans.push_back(minHeap.top().second);
            minHeap.pop();
        }
        return ans;
    }
};

